"use client"

import * as React from "react"
import { ScrollArea as ScrollAreaPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { scrollThumbRecipe, scrollTrackRecipe } from "@/lib/ink/recipes/scroll-area-ink"
import { cn } from "@/lib/utils"

function ScrollArea({
  className,
  children,
  bleed = false,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Root> & {
  bleed?: boolean
  orientation?: "vertical" | "horizontal" | "both"
}) {
  return (
    <ScrollAreaPrimitive.Root data-slot="scroll-area" className={cn("relative", className)} {...props}>
      <ScrollAreaPrimitive.Viewport
        data-slot="scroll-area-viewport"
        className={cn(
          "size-full rounded-[inherit] transition-[color,box-shadow] outline-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-(--ll-focus)",
          orientation === "vertical" && "[&>div]:block!",
          bleed && "p-3"
        )}
      >
        {children}
      </ScrollAreaPrimitive.Viewport>
      {orientation !== "horizontal" ? <ScrollBar /> : null}
      {orientation !== "vertical" ? <ScrollBar orientation="horizontal" /> : null}
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  )
}

function ScrollBar({
  className,
  orientation = "vertical",
  seed,
  ref,
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.ScrollAreaScrollbar> & {
  seed?: string | number
}) {
  const track = useInk({ recipe: scrollTrackRecipe, params: { orientation }, kind: "track", seed: seed === undefined ? undefined : `${seed}|track`, still: true })
  const thumb = useInk({ recipe: scrollThumbRecipe, params: { orientation }, kind: "thumb", seed: seed === undefined ? undefined : `${seed}|thumb`, still: true })
  return (
    <ScrollAreaPrimitive.ScrollAreaScrollbar
      data-slot="scroll-area-scrollbar"
      orientation={orientation}
      ref={useMergedRef<HTMLDivElement>(track.hostRef, ref)}
      {...(track.node ? track.hostProps : {})}
      className={cn(
        "isolate flex touch-none p-px transition-colors select-none forced-colors:outline-0! data-[state=hidden]:animate-out data-[state=hidden]:fade-out-0 data-[state=visible]:animate-in data-[state=visible]:fade-in-0",
        orientation === "vertical" && "h-full w-2.5 border-l border-l-transparent",
        orientation === "horizontal" && "h-2.5 flex-col border-t border-t-transparent",
        className
      )}
      {...props}
    >
      {track.node}
      <ScrollAreaPrimitive.ScrollAreaThumb
        data-slot="scroll-area-thumb"
        ref={thumb.hostRef}
        {...(thumb.node ? thumb.hostProps : {})}
        className="relative isolate flex-1 forced-colors:bg-[CanvasText] forced-colors:outline-0!"
      >
        {thumb.node}
      </ScrollAreaPrimitive.ScrollAreaThumb>
    </ScrollAreaPrimitive.ScrollAreaScrollbar>
  )
}

export { ScrollArea, ScrollBar }

import { pen } from '@/lib/ink/pens'
import { defineRecipe } from '@/lib/ink/recipes'
import type { Pt } from '@/lib/ink/types'
import { RULER } from '@/lib/ink/shapes'

export type ScrollOrientation = 'vertical' | 'horizontal'

function along(o: ScrollOrientation, len: number, mid: number, inset: number): Pt[] {
  const end = inset + Math.max(1, len - 2 * inset)
  return o === 'vertical' ? [[mid, inset], [mid, end]] : [[inset, mid], [end, mid]]
}

export const scrollTrackRecipe = defineRecipe<{ orientation: ScrollOrientation }>({
  id: 'scroll-track',
  kind: 'track',
  layers: ['rest'],
  pad: 2,
  draw(ink, { w, h }, { orientation }) {
    const vertical = orientation === 'vertical'
    const len = vertical ? h : w
    const mid = (vertical ? w : h) / 2
    ink.layer('rest', () => {
      ink.stroke(along(orientation, len, mid, 2), 'pencil.fine', { ...RULER, alpha: 0.4 })
    })
  },
})

const LEAD = pen('pencil', { W: 3.6, dryAmt: 0.3, dryWl: 9, dens: 0.9, wob: { amp: 0.5, wl: 80, tr: 0.15 } })

export const scrollThumbRecipe = defineRecipe<{ orientation: ScrollOrientation }>({
  id: 'scroll-thumb',
  kind: 'thumb',
  layers: ['rest', 'hover'],
  pad: 1,
  draw(ink, { w, h }, { orientation }, ctx) {
    const vertical = orientation === 'vertical'
    const len = vertical ? h : w
    const mid = (vertical ? w : h) / 2
    ink.layer('rest', () => {
      ink.stroke(along(orientation, len, mid, 1), ctx.calm ? 'pencil.fine' : LEAD, { ...RULER, width: ctx.calm ? 1.5 : 1 })
    })
    if (!ctx.calm && len > 44) {
      ink.layer('rest', () => {
        for (const d of [-3.2, 3.2]) {
          const c = len / 2 + d
          const a: Pt = vertical ? [mid - 3.6, c] : [c, mid - 3.6]
          const b: Pt = vertical ? [mid + 3.6, c] : [c, mid + 3.6]
          ink.stroke([a, b], 'pencil.fine', { ...RULER, alpha: 0.85, simple: true })
        }
      })
    }
    ink.layer('hover', () => {
      ink.stroke(along(orientation, len, mid + 0.7, 2), pen('pencil', { W: 2, alpha: 0.7 }), RULER)
    })
  },
})

